def compute(vars):
    canada_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return {"value": None, "trace": {
            "canada_revenue": canada_revenue,
            "total_revenue": total_revenue,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }}

    ratio = canada_revenue / total_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "canada_revenue": canada_revenue,
            "total_revenue": total_revenue,
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }
    }
